SELECT Host,Db,User,Select_priv,Insert_priv,Update_priv
FROM mysql.db
WHERE User='reader' AND Host='localhost' ORDER BY Db;

SELECT Db,Table_name,Table_priv,Column_priv
FROM mysql.tables_priv WHERE User='reader' AND Host='localhost';
SELECT Db,Table_name,Column_name,Column_priv
FROM mysql.columns_priv WHERE User='reader' AND Host='localhost';

# 在操作系统终端中阅读这一连接命令
mysql --host=localhost --user=reader --password
# 成功进入mysql提示符后输入
SELECT CURRENT_USER();
QUIT;

SELECT CURRENT_USER();
-- 仅在确认当前身份为root@localhost且已准备凭据接管时阅读下一句
ALTER USER 'root'@'localhost' IDENTIFIED BY RANDOM PASSWORD;

-- 前置：library.books存在；read_catalog@localhost已建立
GRANT SELECT ON library.books TO 'read_catalog'@'localhost';
SHOW GRANTS FOR 'read_catalog'@'localhost';

-- 前置：该账户确有此表级INSERT直接授权
REVOKE INSERT ON library.books FROM 'catalog_writer'@'localhost';
SHOW GRANTS FOR 'catalog_writer'@'localhost';

SHOW GRANTS;
SHOW GRANTS FOR 'read_catalog'@'localhost';
SELECT CURRENT_ROLE();

-- 管理员检查配置
SELECT User,Host,account_locked FROM mysql.user WHERE User='reader';
-- 在实际业务连接会话中检查所选账户
SELECT CURRENT_USER();

-- 前置：当前账户仅有library.books的SELECT，无其他写入授权
SELECT id,title FROM library.books ORDER BY id;
UPDATE library.books SET title='改名' WHERE id=1;

SET SESSION block_encryption_mode='aes-256-cbc';
SET @k=RANDOM_BYTES(32);
SET @iv=RANDOM_BYTES(16);
SET @cipher=AES_ENCRYPT('catalog note',@k,@iv);
SELECT CAST(AES_DECRYPT(@cipher,@k,@iv) AS CHAR CHARACTER SET utf8mb4) AS plain;

CREATE ROLE 'catalog_read';
GRANT SELECT ON library.books TO 'catalog_read';
GRANT 'catalog_read' TO 'reader'@'localhost';
SET DEFAULT ROLE 'catalog_read' TO 'reader'@'localhost';
SHOW GRANTS FOR 'reader'@'localhost' USING 'catalog_read';

CREATE USER 'audit_report'@'localhost' IDENTIFIED BY RANDOM PASSWORD ACCOUNT LOCK;
GRANT SELECT ON library.books TO 'audit_report'@'localhost';
SHOW GRANTS FOR 'audit_report'@'localhost';
ALTER USER 'audit_report'@'localhost' ACCOUNT UNLOCK;
